from datetime import datetime, timezone
from app.extensions import db


class AllocationRecommendation(db.Model):
    """Scored recommendation candidate generated by smart allocation engine."""
    __tablename__ = 'allocation_recommendations'

    id = db.Column(db.Integer, primary_key=True)
    request_id = db.Column(db.Integer, db.ForeignKey('shelter_requests.id', ondelete='CASCADE'), nullable=False, index=True)
    shelter_id = db.Column(db.Integer, db.ForeignKey('shelters.id', ondelete='CASCADE'), nullable=False, index=True)
    
    # Recommendation scoring breakdown (0-100 scale)
    total_score = db.Column(db.Float, nullable=False)
    distance_km = db.Column(db.Float, nullable=True)
    distance_score = db.Column(db.Float, nullable=False, default=0.0)
    capacity_score = db.Column(db.Float, nullable=False, default=0.0)
    facility_score = db.Column(db.Float, nullable=False, default=0.0)
    pressure_penalty = db.Column(db.Float, nullable=False, default=0.0)
    
    # Explainability details
    is_fully_eligible = db.Column(db.Boolean, nullable=False, default=True)
    explanation = db.Column(db.Text, nullable=False)
    unmet_criteria = db.Column(db.String(256), nullable=True)
    
    created_at = db.Column(db.DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)

    # Relationship
    shelter = db.relationship('Shelter', backref=db.backref('recommendations', lazy='dynamic'))

    def to_dict(self):
        return {
            'id': self.id,
            'request_id': self.request_id,
            'shelter_id': self.shelter_id,
            'shelter_name': self.shelter.name if self.shelter else 'Unknown',
            'shelter_code': self.shelter.shelter_code if self.shelter else '',
            'total_score': round(self.total_score, 1),
            'distance_km': round(self.distance_km, 2) if self.distance_km is not None else None,
            'distance_score': round(self.distance_score, 1),
            'capacity_score': round(self.capacity_score, 1),
            'facility_score': round(self.facility_score, 1),
            'pressure_penalty': round(self.pressure_penalty, 1),
            'is_fully_eligible': self.is_fully_eligible,
            'explanation': self.explanation,
            'unmet_criteria': self.unmet_criteria
        }


class ConfirmedAllocation(db.Model):
    """Officially confirmed household-to-shelter placement."""
    __tablename__ = 'confirmed_allocations'

    id = db.Column(db.Integer, primary_key=True)
    request_id = db.Column(db.Integer, db.ForeignKey('shelter_requests.id', ondelete='CASCADE'), unique=True, nullable=False, index=True)
    shelter_id = db.Column(db.Integer, db.ForeignKey('shelters.id', ondelete='RESTRICT'), nullable=False, index=True)
    people_count = db.Column(db.Integer, nullable=False)
    
    # Coordinator who approved
    confirmed_by_user_id = db.Column(db.Integer, db.ForeignKey('users.id', ondelete='SET NULL'), nullable=True)
    confirmed_at = db.Column(db.DateTime, default=lambda: datetime.now(timezone.utc), nullable=False)
    
    # Check-in progression: 'Pending Check-In', 'Checked In', 'Departed / Checked Out', 'Cancelled'
    check_in_status = db.Column(db.String(32), nullable=False, default='Pending Check-In', index=True)
    check_in_time = db.Column(db.DateTime, nullable=True)
    check_out_time = db.Column(db.DateTime, nullable=True)
    
    # Overrides & notes
    is_override = db.Column(db.Boolean, nullable=False, default=False)
    override_reason = db.Column(db.String(256), nullable=True)
    notes = db.Column(db.Text, nullable=True)

    # Relationships
    confirmed_by = db.relationship('User', foreign_keys=[confirmed_by_user_id])

    def to_dict(self):
        return {
            'id': self.id,
            'request_id': self.request_id,
            'request_code': self.request.request_code if self.request else None,
            'household_alias': self.request.household_alias if self.request else None,
            'shelter_id': self.shelter_id,
            'shelter_name': self.shelter.name if self.shelter else None,
            'people_count': self.people_count,
            'confirmed_by': self.confirmed_by.full_name if self.confirmed_by else 'System Coordinator',
            'confirmed_at': self.confirmed_at.isoformat() if self.confirmed_at else None,
            'check_in_status': self.check_in_status,
            'check_in_time': self.check_in_time.isoformat() if self.check_in_time else None,
            'is_override': self.is_override,
            'override_reason': self.override_reason
        }
